-- ============================================================
-- OPR Unit Profile Assigner — Global script, generated by opr_list_to_lua.sh
-- Source list: ++ HDF Into The Frontier - Human Defense Force (v3.5.3) [GFSQAI 1190pts] [15 Units] ++
--
-- What this does:
--   - Right-click any unassigned model -> pick a unit from the list
--     to assign it. Assignment INJECTS a self-contained script into
--     that specific model (via setLuaScript + reload), so the model
--     keeps working — name, tooltip, wound tracking — even if you
--     save it individually and load it into a totally different
--     game with no Global script at all.
--   - Once assigned, a model manages itself: its own right-click
--     menu ("Take Wound" / "Heal Wound", applying to your whole
--     current selection) lives in ITS OWN script from that point on.
--   - The model's Name field shows the unit name, Quality/Defense,
--     and current/max Tough, all colored via TTS's own BBCode —
--     visible without even hovering. The tooltip (hover) adds the
--     full stat line, abilities, and equipment.
--   - This Global script's only ongoing job is offering the unit
--     list to models that don't have a script yet.
--
-- Install:
--   Right-click the table -> Scripting -> Lua Script -> paste this
--   in, then Save & Play. (If TTS says "no save found", create a
--   save via Games -> Save & Load -> Create first, then re-save
--   the script — see previous notes on that.)
--
-- Note on models assigned under an earlier version of this script:
--   Those models never got their own script, so they'll show up as
--   "unassigned" here again — just right-click and pick their unit
--   once more to bring them onto this version.
--
-- Regenerate:
--   Re-run opr_list_to_lua.sh whenever your list changes, rather
--   than hand-editing UNIT_PROFILES below.
-- ============================================================

-- Set true if you only want the menu added to objects tagged
-- "Figurine" (most official minis/tokens carry that tag).
local ONLY_FIGURINES = false

local UNIT_PROFILES = {
