    rules = "Hold the Line. Equipment: Rifle (24\", A3), CCW (A3)",
  },
  -- 3x unit(s), 1 model(s) each | 55pts
  ["GRUNT Robot"] = {
    stats = "Quality 5+ | Defense 5+ | Tough 3",
    rules = "Fearless, Good Shot, Hold the Line. Equipment: Rifle (24\", A3), CCW (A3)",
  },
  -- 1x unit(s), 1 model(s) each | 105pts
  ["Company Leader"] = {
    stats = "Quality 4+ | Defense 5+ | Tough 9",
    rules = "Hero, Hold the Line. Equipment: Master Pistol (12\", A6), CCW (A6)",
  },
  -- 1x unit(s), 1 model(s) each | 115pts
  ["Drill Sergeant"] = {
    stats = "Quality 4+ | Defense 5+ | Tough 9",
    rules = "Hero, Hold the Line, Bane in Melee Buff. Equipment: Master Pistol (12\", A6), CCW (A6)",
  },
  -- 1x unit(s), 1 model(s) each | 125pts
  ["Enforcer"] = {
    stats = "Quality 4+ | Defense 5+ | Tough 9",
    rules = "Hero, Hold the Line, No Retreat Buff. Equipment: Master Pistol (12\", A6), CCW (A6)",
  },
  -- 1x unit(s), 1 model(s) each | 125pts
  ["Weapon Team"] = {
    stats = "Quality 5+ | Defense 5+ | Tough 9",
    rules = "Hold the Line. Equipment: Mortar (30\", A3, Blast(3), Indirect), Crew (A6)",
