  -- 1x unit(s), 1 model(s) each | 135pts
  ["Colonel Rixxon"] = {
    stats = "Quality 4+ | Defense 5+ | Tough 9",
    rules = "Hero, Unique, Hold the Line, Morale Debuff. Equipment: Master Pistol (12\", A6), Energy Sword (A6, AP(1), Rending)",
  },
  -- 1x unit(s), 1 model(s) each | 165pts
